// === Tab: mySketch ===
//for the #wccChallenge on the theme of "A Foggy Forest".
//Love that we just combined two themes because of a tie and I went ahead and added a runner-up theme
//and made a "foggy forested island"
//tried to recreate (in a folk arty style) the lovely north woods ponds we have around these parts and near were I grew up
//they are so peaceful and mysterious on a foggy morning, with the loons calling
//If only I could be on a kayak gliding across this pond right now.

//title is from a lyric by R.A.P. Ferreira


treePos=[]
let fog=[]
let stillness
let loon

// function preload() {
//  loon = loadSound('https://openprocessing.org/sketch/1736360/files/loon.mp3')
// }


function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1)
	stillness= createGraphics(windowWidth, windowHeight)
	for(let i=0; i<5; i++){
		fog.push(new fogbank(random(width), random(height/2, height)))
	}

	//placing trees to set up island

	farthestL=width/2
	farthestR=width/2
	for(let i=0; i<50; i++){
		let x=random(width/2-width/4, width/2+width/4)
		let y=random(height/2-height/30, height/2+height/30)
		treePos.push(createVector(x, y))
		if(x<farthestL){
			farthestL=x
		}
		if(x>farthestR){
			farthestR=x
		}
		let r=farthestR-width/2
		let l=width/2- farthestL
		if(r<l){
			extent=l+40
		} else{
			extent=r+40
		}
	}

	//sky 

	for(let y=-20; y<height/3-10; y+=3){
	for(let x=-20; x<width+20; x+=3){
		strokeScale=map(y, -20, height/3-10, 3, 0.1)
	stillness.strokeWeight(strokeScale)
		stillness.point(x-noise(x/100, y/10)*7,y+ noise(x/100, y/10)*5)
	}
	}


	//background trees
	for(let y=height/3; y<height/2; y+=20){
		let scalar= map(y, height/4, height/2-height/18, 0.1, 0.5)
	for(let x=-50; x<width+50; x+=10){
		stillness.stroke(125)
		pine(x+random(-10, 10), y+random(-5, 5), scalar)

	}
	}


	//island

	//first, sort the trees by x value
	treePos.sort((a,b) => a.x - b.x);
	stillness.fill(0)


	//then, draw shape using the organized tree coordinates
	stillness.beginShape()
	stillness.curveVertex(farthestL-40, height/2+50)
	for(let i=0; i<treePos.length; i++){
		stillness.curveVertex(treePos[i].x, treePos[i].y)
	}
	stillness.curveVertex(farthestR+40, height/2+50)
	stillness.curveVertex(width/2, height/2+80)
	stillness.curveVertex(farthestL, height/2+70)
	stillness.endShape(CLOSE)
			stillness.noFill()
	stillness.stroke(0)
	for(let i=0; i<treePos.length; i++){
		pine(treePos[i].x, treePos[i].y, 1.5) 		
			}



	//water
}
	function draw(){
		background(244)

	stroke(175)
	noFill()
	push()
	translate(width/2, height/2+height/20)
	for(let i=0; i<height*3.5; i+=50){
	strokeWeight(1)	
	beginShape()
for(let theta=-PI/8; theta<PI+PI/8; theta+=0.1){
	let xer=cos(theta)*((extent+i)/1.8)
	let yer=sin(theta)*((extent+i)/8)
	let xn=map(noise(i/200, theta*10, frameCount/60), 0, 1, -10, 10)
	let yn=map(noise(theta*10, i/200+10,frameCount/60), 0, 1, -10, 10)
	curveVertex(xer+xn, yer+yn)

}
	endShape()
	}
	pop()
		image(stillness, 0, 0)

	if(frameCount%100==0){
		fog.push(new fogbank(-100, random(height/2, height)))
	}

	for(let i=fog.length-1; i>=0; i--){
		fog[i].move();
		fog[i].show();
	}
}

class fogbank{
	constructor(x, y){
		this.x=x
		this.y=y
		this.cloud=[]
		for(let i=0; i<60; i++){
		this.cloud.push(createVector(random(-50, 50), random(-50, 50)))
	}
	}

move(){
	this.x+=0.5
	if(this.x>width+100){
		let index= fog.indexOf(this)
		fog.splice(index, 1)
	}
}
show(){
	push()
	translate(this.x, this.y)
	randomSeed(this.rs)
	for(let i=0; i<this.cloud.length; i++){
		fill(244, 25)
		noStroke()
		ellipse(this.cloud[i].x,this.cloud[i].y, 50, 30)	
	}
	pop()
}

}

function pine(x, y, hScale){
	//x, y are base of tree
	stillness.noFill()
	stillness.push()
	stillness.translate(x, y)
	stillness.scale(hScale)
	let h= random(50, 150)
	stillness.strokeWeight(3)
	stillness.line(0, 0, 0, -h/10)
	for(let y= -h/8; y>-h; y-=3){
		sw=map(y, -h/10, -h, 3, 0.5)
		stillness.strokeWeight(sw)
		stillness.point(0, y)
		stillness.strokeWeight(1)
		arcW=map(y, -h/10, -h, h/4, h/20)
		stillness.arc(-arcW/2, y, arcW, arcW, 0, PI/2)
		stillness.arc(arcW/2, y, arcW, arcW, PI/2, PI)
	}
	for(let i=0; i<30; i++){
		stillness.fill(244, 15)
		stillness.noStroke()
		stillness.ellipse(random(-20, 20), random(-20, 20), random(10, 40), random(10, 40))
	}
	stillness.pop()
}

